const getQuoteNotifyPeople = `-- name: GetQuoteNotifyPeople :one
SELECT
    q.created_by,
    COALESCE(NULLIF(TRIM(u.name || ' ' || u.surname), ''), u.email, '')::text AS created_by_name,
    l.assignee_user_id AS lead_assignee_id,
    c.name AS customer_name
FROM quotes q
JOIN customers c ON c.id = q.customer_id
LEFT JOIN users u ON u.id = q.created_by
LEFT JOIN leads l ON l.id = q.lead_id AND l.organization_id = q.organization_id AND l.deleted_at IS NULL
WHERE q.id = $1 AND q.organization_id = $2
`

type GetQuoteNotifyPeopleParams struct {
	ID             int64 `json:"id"`
	OrganizationID int64 `json:"organization_id"`
}

type GetQuoteNotifyPeopleRow struct {
	CreatedBy      pgtype.Int8 `json:"created_by"`
	CreatedByName  string      `json:"created_by_name"`
	LeadAssigneeID pgtype.Int8 `json:"lead_assignee_id"`
	CustomerName   string      `json:"customer_name"`
}

// Team members related to a quote (creator, lead assignee) for internal notifications.
func (q *Queries) GetQuoteNotifyPeople(ctx context.Context, arg GetQuoteNotifyPeopleParams) (GetQuoteNotifyPeopleRow, error) {
	row := q.db.QueryRow(ctx, getQuoteNotifyPeople, arg.ID, arg.OrganizationID)
	var i GetQuoteNotifyPeopleRow
	err := row.Scan(
		&i.CreatedBy,
		&i.CreatedByName,
		&i.LeadAssigneeID,
		&i.CustomerName,
	)
	return i, err
}

const getQuoteRefs = `-- name: GetQuoteRefs :one
SELECT
    c.uuid AS customer_uuid,
    c.name AS customer_name,
    c.phone AS customer_phone,
    c.email AS customer_email,
    c.tax_id AS customer_tax_id,
    c.tax_office AS customer_tax_office,
    l.uuid AS lead_uuid,
    v.uuid AS vehicle_uuid,
    m.uuid AS vehicle_model_uuid,
    COALESCE(b.name || ' ' || m.name, '')::text AS vehicle_model_label,
    j.uuid AS job_uuid,
    COALESCE(NULLIF(TRIM(u.name || ' ' || u.surname), ''), u.email, '')::text AS created_by_name
FROM quotes q
JOIN customers c ON c.id = q.customer_id
LEFT JOIN leads l ON l.id = q.lead_id
LEFT JOIN customer_vehicles v ON v.id = q.vehicle_id
LEFT JOIN vehicle_models m ON m.id = q.vehicle_model_id
LEFT JOIN vehicle_brands b ON b.id = m.brand_id
LEFT JOIN service_jobs j ON j.id = q.job_id
LEFT JOIN users u ON u.id = q.created_by
WHERE q.id = $1
`

type GetQuoteRefsRow struct {
	CustomerUuid      uuid.UUID   `json:"customer_uuid"`
	CustomerName      string      `json:"customer_name"`
	CustomerPhone     string      `json:"customer_phone"`
	CustomerEmail     string      `json:"customer_email"`
	CustomerTaxID     string      `json:"customer_tax_id"`
	CustomerTaxOffice string      `json:"customer_tax_office"`
	LeadUuid          pgtype.UUID `json:"lead_uuid"`
	VehicleUuid       pgtype.UUID `json:"vehicle_uuid"`
	VehicleModelUuid  pgtype.UUID `json:"vehicle_model_uuid"`
	VehicleModelLabel string      `json:"vehicle_model_label"`
	JobUuid           pgtype.UUID `json:"job_uuid"`
	CreatedByName     string      `json:"created_by_name"`
}

