const listQuotes = `-- name: ListQuotes :many
SELECT
    q.id, q.uuid, q.number, q.status, q.currency, q.grand_total, q.valid_until,
    q.vehicle_plate, q.vehicle_label, q.sent_at, q.viewed_at, q.created_at, q.updated_at,
    c.uuid AS customer_uuid,
    c.name AS customer_name,
    c.phone AS customer_phone,
    l.uuid AS lead_uuid,
    j.uuid AS job_uuid,
    (SELECT COUNT(*)::bigint FROM quote_lines ql WHERE ql.quote_id = q.id) AS line_count
FROM quotes q
JOIN customers c ON c.id = q.customer_id
LEFT JOIN leads l ON l.id = q.lead_id
LEFT JOIN service_jobs j ON j.id = q.job_id
WHERE q.organization_id = $1
  AND ($2::text IS NULL OR q.status = $2
       OR ($2::text = 'open' AND q.status IN ('draft', 'sent', 'viewed')))
  AND ($3::bigint IS NULL OR q.customer_id = $3)
  AND ($4::bigint IS NULL OR q.lead_id = $4)
  AND (
    $5::text IS NULL
    OR q.number ILIKE '%' || $5 || '%'
    OR c.name ILIKE '%' || $5 || '%'
    OR c.phone ILIKE '%' || $5 || '%'
    OR q.vehicle_plate ILIKE '%' || $5 || '%'
  )
ORDER BY
    CASE WHEN $6::text = 'created_at' THEN q.created_at END ASC,
    CASE WHEN $6::text = 'grand_total' THEN q.grand_total END ASC,
    CASE WHEN $6::text = '-grand_total' THEN q.grand_total END DESC,
    CASE WHEN $6::text = 'valid_until' THEN q.valid_until END ASC NULLS LAST,
    q.created_at DESC, q.id DESC
LIMIT $8 OFFSET $7
`

