const nextQuoteNumber = `-- name: NextQuoteNumber :one

INSERT INTO quote_counters (organization_id, year, last_number)
VALUES ($1, $2, 1)
ON CONFLICT (organization_id, year)
DO UPDATE SET last_number = quote_counters.last_number + 1, updated_at = NOW()
RETURNING last_number
`

type NextQuoteNumberParams struct {
	OrganizationID int64 `json:"organization_id"`
	Year           int32 `json:"year"`
}

// Tenant quotes (teklifler). Tenant queries are scoped by organization_id;
// public queries look up by the unguessable share_token only.
func (q *Queries) NextQuoteNumber(ctx context.Context, arg NextQuoteNumberParams) (int32, error) {
	row := q.db.QueryRow(ctx, nextQuoteNumber, arg.OrganizationID, arg.Year)
	var last_number int32
	err := row.Scan(&last_number)
	return last_number, err
}

const quoteSummary = `-- name: QuoteSummary :one
SELECT
    COUNT(*) FILTER (WHERE status IN ('draft', 'sent', 'viewed'))::bigint AS open_count,
    COALESCE(SUM(grand_total) FILTER (WHERE status IN ('sent', 'viewed')), 0)::numeric AS pending_total,
    COUNT(*) FILTER (WHERE status = 'draft')::bigint AS draft_count,
    COUNT(*) FILTER (WHERE status IN ('sent', 'viewed'))::bigint AS awaiting_count,
    COUNT(*) FILTER (WHERE status IN ('sent', 'viewed') AND valid_until IS NOT NULL
        AND valid_until >= $1::date
        AND valid_until <= $1::date + 3)::bigint AS expiring_soon,
    COUNT(*) FILTER (WHERE status = 'accepted' AND accepted_at >= $2::timestamptz)::bigint AS accepted_month,
    COALESCE(SUM(grand_total) FILTER (WHERE status = 'accepted'
        AND accepted_at >= $2::timestamptz), 0)::numeric AS accepted_month_total
FROM quotes
WHERE organization_id = $3 AND currency = $4
`

type QuoteSummaryParams struct {
	Today          pgtype.Date        `json:"today"`
	MonthStart     pgtype.Timestamptz `json:"month_start"`
	OrganizationID int64              `json:"organization_id"`
	Currency       string             `json:"currency"`
}

