func (q *Queries) UpdateQuoteContent(ctx context.Context, arg UpdateQuoteContentParams) (Quote, error) {
	row := q.db.QueryRow(ctx, updateQuoteContent,
		arg.CustomerID,
		arg.LeadID,
		arg.VehicleID,
		arg.VehiclePlate,
		arg.VehicleLabel,
		arg.VehicleModelID,
		arg.VehicleYear,
		arg.Currency,
		arg.PricesIncludeVat,
		arg.DiscountType,
		arg.DiscountValue,
		arg.Subtotal,
		arg.DiscountTotal,
		arg.VatTotal,
		arg.GrandTotal,
		arg.ValidUntil,
		arg.Notes,
		arg.Terms,
		arg.ID,
		arg.OrganizationID,
	)
	var i Quote
	err := row.Scan(
		&i.ID,
		&i.Uuid,
		&i.OrganizationID,
		&i.Number,
		&i.CustomerID,
		&i.LeadID,
		&i.VehicleID,
		&i.VehiclePlate,
		&i.VehicleLabel,
		&i.VehicleModelID,
		&i.VehicleYear,
		&i.Status,
		&i.Currency,
		&i.PricesIncludeVat,
		&i.DiscountType,
		&i.DiscountValue,
		&i.Subtotal,
		&i.DiscountTotal,
		&i.VatTotal,
		&i.GrandTotal,
		&i.ValidUntil,
		&i.Notes,
		&i.Terms,
		&i.ShareToken,
		&i.PdfObjectKey,
		&i.PdfSha256,
		&i.SentAt,
		&i.ViewedAt,
		&i.ViewCount,
		&i.AcceptedAt,
		&i.RejectedAt,
		&i.ExpiredAt,
		&i.CancelledAt,
		&i.DecisionNote,
		&i.DecisionChannel,
		&i.DecisionIp,
		&i.DecisionUserAgent,
		&i.JobID,
		&i.ConvertedAt,
		&i.CreatedBy,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
